const [search, page] = await Promise.all([
  tools.web_search({ queries: ["skills.sh 下载量最高 10 个 skill", "skills.sh leaderboard most installed skills find-skills grill-me"] }),
  tools.web_fetch({ url: "https://skills.sh/" }).catch((e) => ({ error: String(e) })),
]);

console.log("=== SEARCH CONTENT ===");
console.log((search.content ?? "(none)").slice(0, 3000));
console.log("=== SOURCES ===");
for (const s of search.sources.slice(0, 12)) console.log(`- ${s.title ?? ""} :: ${s.url}\n  ${(s.snippet ?? "").slice(0, 200)}`);

console.log("=== skills.sh fetch ===");
const p: any = page;
if (p.error) console.log(p.error);
else {
  console.log("status", p.statusCode, "kind", p.body?.kind, "truncated", p.truncated);
  console.log(String(p.body?.content ?? "").slice(0, 4000));
}
